#!/usr/bin/env python3
#
# merge_ligand.py - Merge OpenFF-parametrized ligands into protein topology
#
# Inserts ligand ITP includes and coordinates into the protein topology and
# GRO file generated by pdb2gmx. Handles chain assignment for pulling.
#
# Usage: python merge_ligand.py -t topol.top -c conf.gro -m chain_map.gs --ligand-param on
#
# EVERY EXTRACTED LIGAND IS ACCOUNTED FOR. The ligand_*.pdb files renumber_pdb.py
# extracted are the list of what the crystal holds; this script decides, for each
# of them, whether it reaches topol.top, and rewrites ligand_failed.gs (format and
# meaning in parametrize_ligand.py) to hold exactly the instances that
#   - lie within the simulated region but have no parameters (their reason from
#     parametrize_ligand.py when it left one),
#   - were built but are known not to be the deposited molecule, or
#   - are covalently bonded to the protein or to another ligand, a link the
#     pipeline does not model, so they would be simulated detached (a glycan that
#     fuse_glycans.py fused with its amino acid is protein by now, also here: the
#     deposited protein is read from fused.pdb, where its sugars are ATOM records), or
#   - are sugars of a glycan fuse_glycans.py left as ligands: each carries its reason
#     from glycan_unfused.gs, also when the covalent rule finds no bond here (the rest
#     of a glycan whose deposited link is longer than the rule and that
#     fuse_glycans.py could not join, as 1FZC NAG K 2 at 1.85 A was before it joined
#     such links, was merged as a free molecule; fusion review F1, F6). A sugar fused
#     through a joined stretched link (up to 2.5 A) is an ATOM record of its fused
#     residue in fused.pdb, so it is protein here like any fused sugar.
# A ligand more than LIGAND_PROXIMITY_CUTOFF from every atom of the (cutout)
# protein is outside the simulated region by design and is not a failure, whether
# or not it could be parametrised.
#
# --ligand-param says whether parametrisation ran, which the runners know and this
# script cannot tell from the files (contract F4):
#   on        parametrize_ligand.py ran: the reconciliation above.
#   off-user  the user passed --no-ligand-param: no ligand is merged, the left-out
#             ones are named on stdout, and nothing goes into ligand_failed.gs.
#   off-ff    the force field has no ligand parametrisation (charmm36, gromos54a8,
#             gromos54a8_rf): no ligand is merged, and every in-region one gets the
#             line 'not parametrised: force field <ff> has no ligand parametrisation;
#             pass --no-ligand-param to run without ligands'.
# Without the option: 'on' when a manifest (or a line parametrize_ligand.py wrote)
# shows that parametrisation ran, else 'off-ff', so a caller that says nothing fails
# closed. The first version wrote nothing whenever parametrisation had not run, so a
# GROMOS 54A8 FE run went ahead without every interface ligand, noted on stdout only.
#
# On the 2026-09 HADDOCK pass the previous version merged 1WQ1 and 1GRN without
# their AlF3 and printed nothing (the instance simply had no manifest line), and it
# took each ligand's chain from ligand_info.gs by line number although that file is
# in PDB order and the manifest in file-glob order with failures left out: in 2FD6
# the PGE of chain H went into protein B's group and the NDG of chain U into A's.
#

import os
import sys
import glob
import argparse

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from parametrize_ligand import (pdb_atoms, instance_of, element_of, select_altloc,  # noqa: E402
                                LIGAND_FAILED, MANIFEST)
# What 'covalently bonded' means (radii, slack, the clash limits and why) lives in
# covalent.py, which fuse_glycans.py uses too: the sugars of a glycan it leaves unfused
# are bonded here by the same rule.
from covalent import COVALENT_RADII, COVALENT_SLACK, contact_kind  # noqa: E402

parser = argparse.ArgumentParser(description="Merge ligand topology and coordinates into protein system.")
parser.add_argument('-t', '--topol', type=str, default="topol.top", help="Protein topology file")
parser.add_argument('-c', '--conf', type=str, required=True, help="Protein coordinate file (GRO)")
parser.add_argument('-m', '--chainmap', type=str, required=True, help="Chain map file (chain_map.gs)")
parser.add_argument('--ligand-param', choices=("on", "off-user", "off-ff"), default=None,
                    help="did ligand parametrisation run: on; off-user (--no-ligand-param); off-ff (the force "
                         "field has none). Default: on when a manifest exists, else off-ff")
args = parser.parse_args()

BASE = os.path.dirname(args.chainmap)
FAILED_PATH = os.path.join(BASE, LIGAND_FAILED)

LIGAND_PROXIMITY_CUTOFF = 0.5  # nm: any ligand atom must be within this distance of a protein atom

# Structural ions as renumber_pdb.py keeps them: metal coordination to a ligand
# (Mg to a phosphate oxygen at 0.20-0.21 nm) is not a covalent link to model.
ION_RESIDUES = {"BA", "CA", "CD", "CL", "CO", "CS", "CU", "CU1", "FE", "FE2", "HG", "K", "LI", "MG",
                "MN", "NA", "NI", "PB", "SD", "SR", "ZN"}
# Why fuse_glycans.py left a glycan's sugars as ligands: 'RESNAME CHAIN RESNUM reason',
# one line per sugar, written beside the chain map. A sugar with such a line in the
# simulated region is a failure with that reason in its ligand_failed.gs line, after
# any other reason it has, so the LIGAND_FAIL of a glycan says why it was not fused
# (over the size cap, not all saccharides, its fused residue failed to parametrise,
# ...). The covalent rule itself is the same for every ligand.
GLYCAN_UNFUSED = "glycan_unfused.gs"
# Reasons this script adds start with MERGE_TAG, or are the off-ff line. They are
# re-derived on every run, so a repeated merge drops its own earlier ones and keeps
# only parametrize_ligand.py's.
MERGE_TAG = "merge: "
OFF_FF_REASON = ("not parametrised: force field %s has no ligand parametrisation; pass --no-ligand-param "
                 "to run without ligands")
OFF_FF_TAG = "not parametrised: force field "


def read_gro_coords(path, max_atoms=None):
    """Read coordinates from GRO file using fixed-width format (positions 20-44)."""
    coords = []
    with open(path) as f:
        lines = f.readlines()
    n = int(lines[1].strip())
    if max_atoms:
        n = min(n, max_atoms)
    for line in lines[2:2 + n]:
        try:
            x = float(line[20:28])
            y = float(line[28:36])
            z = float(line[36:44])
            coords.append((x, y, z))
        except (ValueError, IndexError):
            pass
    return coords


def deposited_protein(base):
    """[(label, ELEMENT, x, y, z)] (nm) of the deposited protein's heavy atoms: the
    ATOM records of fused.pdb, where the sugars of a fused glycan are ATOM records of
    its residue, else of input.pdb (renumbered.pdb when there is none), ions left out.
    Returns None when no such file exists."""
    for fname in ("fused.pdb", "input.pdb", "renumbered.pdb"):
        path = os.path.join(base, fname)
        if not os.path.isfile(path):
            continue
        out = []
        with open(path) as f:
            for line in f:
                if not line.startswith("ATOM  ") or line[17:20].strip() in ION_RESIDUES:
                    continue
                name = line[12:16].strip()
                el = element_of(line.rstrip("\n"))
                if el in ("H", ""):
                    continue
                out.append(("%s %s %s %s" % (line[17:20].strip(), line[21], line[22:27].strip(), name), el,
                            float(line[30:38]) / 10.0, float(line[38:46]) / 10.0, float(line[46:54]) / 10.0))
        return out
    return None


def ff_defines_moleculetype(topol, name):
    """Does topol.top, or a file it includes, define [ moleculetype ] `name`?
    True/False, or None when an include could not be found (then grompp decides)."""
    import re
    tdir = os.path.dirname(os.path.abspath(topol))
    dirs = [tdir] + [d for d in os.environ.get("GMXLIB", "").split(":") if d]
    if os.environ.get("GMXDATA"):
        dirs.append(os.path.join(os.environ["GMXDATA"], "top"))
    files, unresolved = [topol], False
    with open(topol) as f:
        for line in f:
            m = re.match(r'\s*#include\s+"([^"]+)"', line)
            if not m:
                continue
            hit = next((os.path.join(d, m.group(1)) for d in dirs if os.path.isfile(os.path.join(d, m.group(1)))), None)
            if hit:
                files.append(hit)
            else:
                unresolved = True
    for path in files:
        want = False
        with open(path) as f:
            for line in f:
                s = line.split(";")[0].strip()
                if not s:
                    continue
                if s.startswith("["):
                    want = s.strip("[] ") == "moleculetype"
                    continue
                if want:
                    if s.split()[0] == name:
                        return True
                    want = False
    return None if unresolved else False


def forcefield_name(topol):
    """The force field topol.top includes ('amber19sb', 'charmm36-jul2022', ...), for messages."""
    import re
    try:
        with open(topol) as f:
            for line in f:
                m = re.match(r'\s*#include\s+"(?:[^"]*/)?([^/"]+)\.ff/forcefield\.itp"', line)
                if m:
                    return m.group(1)
    except OSError:
        pass
    return "of this run"


# ---- What was extracted: one instance per ligand_*.pdb (one conformer of an altloc ligand) ----
instances = []
for path in sorted(glob.glob(os.path.join(BASE, "ligand_*.pdb"))):
    with open(path) as f:
        text, _ = select_altloc(f.read())
    atoms = [a for a in pdb_atoms(text) if a[1] != "H"]
    instances.append({"file": os.path.basename(path), "key": instance_of(text),
                      "atoms": [(a[0], a[1], a[2] / 10.0, a[3] / 10.0, a[4] / 10.0) for a in atoms],
                      "entry": None})

# ---- What was parametrised: ligand_manifest.gs (written by parametrize_ligand.py) ----
# Format: mol_name  itp_path  atomtypes_path  gro_path  natoms  [chain  resnum  source_pdb]
# itp_path "-" marks a force-field ion: its moleculetype comes with topol.top.
manifest_path = os.path.join(BASE, MANIFEST)
entries = []
if os.path.isfile(manifest_path):
    with open(manifest_path) as f:
        for line in f:
            if line.strip().startswith("#") or not line.strip():
                continue
            parts = line.rstrip("\n").split("\t") if "\t" in line else line.split()
            if len(parts) >= 5:
                entries.append({"mol_name": parts[0], "itp": parts[1], "atomtypes": parts[2], "gro": parts[3],
                                "natoms": int(parts[4]), "chain": parts[5] if len(parts) > 5 else "",
                                "source": parts[7] if len(parts) > 7 else "", "line": line.rstrip("\n")})
elif os.path.isfile(os.path.join(BASE, "ligand_info.gs")):
    # Legacy layout (before ligand_manifest.gs): one shared ITP per residue name
    for inst in instances:
        resname, chain = inst["key"][0], inst["key"][1]
        itp = f"ligand_{resname}.itp"
        gro = f"ligand_{resname}_{chain}.gro"
        if not os.path.isfile(gro):
            gro = f"ligand_{resname}.gro"
        if os.path.isfile(itp) and os.path.isfile(gro):
            entries.append({"mol_name": resname, "itp": itp, "atomtypes": f"ligand_{resname}_atomtypes.itp",
                            "gro": gro, "natoms": 0, "chain": chain, "source": inst["file"], "line": None})

# Each line to its extracted instance: by source file; a line without one (older
# manifest) by residue name and chain, first come first served.
by_file = {inst["file"]: inst for inst in instances}
for e in entries:
    inst = by_file.get(e["source"])
    if inst is None and not e["source"]:
        base_name = e["mol_name"].rsplit("_", 1)[0] if e["mol_name"].rsplit("_", 1)[-1].isdigit() else e["mol_name"]
        chain = e["chain"] or e["gro"][:-4].rsplit("_", 1)[-1]
        inst = next((i for i in instances if i["entry"] is None and i["key"][0] == base_name
                     and i["key"][1] == chain), None)
    if inst is None:
        # Parametrised but no extracted PDB to match (it was removed): merge it as before.
        inst = {"file": None, "key": (e["mol_name"], e["chain"] or "-", "0"), "atoms": [], "entry": None}
        instances.append(inst)
    inst["entry"] = e

# ---- parametrize_ligand.py's own verdicts, by instance ----
prior = {}
if os.path.isfile(FAILED_PATH):
    with open(FAILED_PATH) as f:
        for line in f:
            p = line.split(None, 3)
            if len(p) >= 3:
                reason = "; ".join(s for s in (p[3].strip() if len(p) > 3 else "no reason recorded").split("; ")
                                   if not s.startswith((MERGE_TAG, OFF_FF_TAG)) and not s.startswith("pass --no-ligand"))
                if reason:
                    prior[tuple(p[:3])] = reason

# ---- fuse_glycans.py's reasons for the glycans it left as ligands, by instance ----
# A ';' inside such a reason becomes ',': the line keeps its own reasons apart by '; ',
# and a re-run of this script would otherwise take the pieces after the first ';' for
# parametrize_ligand.py's verdicts and write them twice.
unfused = {}
if os.path.isfile(os.path.join(BASE, GLYCAN_UNFUSED)):
    with open(os.path.join(BASE, GLYCAN_UNFUSED)) as f:
        for line in f:
            p = line.split(None, 3)
            if len(p) == 4:
                unfused[tuple(p[:3])] = " ".join(p[3].replace(";", ",").split())

mode = args.ligand_param
if mode is None:
    mode = "on" if (os.path.isfile(manifest_path) or entries or prior) else "off-ff"
    print(f"--ligand-param not given: {mode} ("
          + ("a ligand manifest or parametrisation record exists" if mode == "on"
             else "no manifest and no parametrisation record, so parametrisation did not run") + ")")
if mode != "on":
    # Parametrisation did not run in this setup, so any manifest here is stale: merge nothing from it.
    for inst in instances:
        inst["entry"] = None
    instances = [i for i in instances if i["file"] is not None]
    prior = {}
FF_NAME = forcefield_name(args.topol)

if not instances:
    print("No ligand_manifest.gs or ligand_info.gs found, skipping ligand merge.")
    if os.path.isfile(FAILED_PATH):
        os.remove(FAILED_PATH)   # nothing was extracted, so any line in it is stale
    sys.exit(0)

# Filter ligands by proximity to existing protein atoms (skip distant buffer molecules)
import numpy as np
from scipy.spatial.distance import cdist

prot_coords = read_gro_coords(args.conf)
prot_arr = np.array(prot_coords) if prot_coords else None
prot_heavy = deposited_protein(BASE)
if prot_heavy is None:
    prot_heavy = []
    print("Warning: no fused.pdb, input.pdb or renumbered.pdb beside the chain map; covalent links to the "
          "protein are not checked")


def lig_coords(inst):
    """(coordinates in nm, proximity limit). A parametrised ligand is measured with
    its hydrogens from its .gro, as always. One without parameters only has the
    heavy atoms of its PDB, and its hydrogens would reach up to one C-H bond
    (0.11 nm) closer, so it gets that much more room: an unparametrised ligand is
    only ever called outside the simulated region when it certainly is."""
    e = inst["entry"]
    if e is not None and os.path.isfile(e["gro"]):
        c = read_gro_coords(e["gro"])
        if c:
            return c, LIGAND_PROXIMITY_CUTOFF
    return [a[2:] for a in inst["atoms"]], LIGAND_PROXIMITY_CUTOFF + 0.11


def bonded_partner(inst, others):
    """(kind, 'what it touches (distance)') for the closest covalent contact ('bond'), or
    when there is none the closest overlap ('clash'); None when neither exists."""
    found = {"bond": None, "clash": None}
    lig = [a for a in inst["atoms"] if a[1] in COVALENT_RADII]
    if not lig:
        return None
    L = np.array([a[2:] for a in lig])
    for label, pool in [("protein", prot_heavy)] + others:
        pool = [a for a in pool if a[1] in COVALENT_RADII]
        if not pool:
            continue
        d = cdist(L, np.array([a[2:] for a in pool])) * 10.0          # A
        lim = (np.array([COVALENT_RADII[a[1]] for a in lig])[:, None]
               + np.array([COVALENT_RADII[b[1]] for b in pool])[None, :] + COVALENT_SLACK)
        for i, j in zip(*np.nonzero(d < lim)):
            kind = contact_kind(lig[i][1], pool[j][1], d[i, j])
            if kind and (found[kind] is None or d[i, j] < found[kind][0]):
                found[kind] = (d[i, j], "%s %s to %s %s (%.2f A)" % (inst["key"][0], lig[i][0], label, pool[j][0],
                                                                     d[i, j]))
    for kind in ("bond", "clash"):
        if found[kind]:
            return kind, found[kind][1]
    return None


failed = {}           # key -> reason, in instance order
available_ligands = []
not_parametrised = []
for inst in instances:
    key, e = inst["key"], inst["entry"]
    name = e["mol_name"] if e else key[0]
    usable = e is not None and os.path.isfile(e["gro"]) and (e["itp"] == "-" or os.path.isfile(e["itp"]))
    coords, limit = lig_coords(inst)
    if prot_arr is not None and coords:
        min_dist = cdist(np.array(coords), prot_arr).min()
        if min_dist > limit:
            print(f"Skipping {name} chain {key[1]}: nearest protein atom {min_dist:.2f} nm (> {limit:.2f} nm)"
                  + ("" if usable else "; outside the simulated region, so its missing parameters do not matter"))
            continue
    if mode == "off-user":
        not_parametrised.append(inst)
        continue
    if mode == "off-ff":
        failed[key] = OFF_FF_REASON % FF_NAME
        continue
    glycan = [MERGE_TAG + "glycan not fused: " + unfused[key]] if key in unfused else []
    if not usable:
        if e is None:
            reason = prior.get(key, MERGE_TAG + "parametrisation left no ligand_manifest.gs entry and no reason")
            print(f"Warning: no parameters for {key[0]} chain {key[1]} residue {key[2]} ({reason}), skipping it")
        else:
            reason = prior.get(key, MERGE_TAG + f"{e['itp']} or {e['gro']} not found")
            print(f"Warning: {e['itp']} or {e['gro']} not found, skipping {name} chain {key[1]}")
        failed[key] = "; ".join([reason] + glycan)
        continue
    if e["itp"] == "-":
        known = ff_defines_moleculetype(args.topol, name)
        if known is False:
            failed[key] = MERGE_TAG + f"the force field in {args.topol} defines no moleculetype {name} for this ion"
            print(f"Warning: {args.topol} defines no moleculetype {name}, skipping {key[0]} chain {key[1]}")
            continue
        if known is None:
            print(f"Warning: could not open every file {args.topol} includes; grompp will tell whether "
                  f"moleculetype {name} exists")
    reasons = []
    if key in prior:
        reasons.append(prior[key])
    contact = bonded_partner(inst, [("%s %s %s" % o["key"], o["atoms"]) for o in instances
                                    if o is not inst and o["atoms"]])
    if contact and contact[0] == "bond":
        reasons.append(MERGE_TAG + "covalently bonded in the deposited model, " + contact[1] + ", a link the "
                       "pipeline does not model, so the ligand would be simulated detached")
        print(f"Warning: {key[0]} chain {key[1]} residue {key[2]} is covalently bonded: {contact[1]}"
              + (f"; glycan not fused: {unfused[key]}" if key in unfused else ""))
    elif contact:
        print(f"Warning: clash in the deposited model, not a bond: {contact[1]} is shorter than any bond "
              f"between these elements; {key[0]} chain {key[1]} residue {key[2]} is merged and minimisation "
              f"separates the atoms")
    if glycan and not (contact and contact[0] == "bond"):
        print(f"Warning: {key[0]} chain {key[1]} residue {key[2]} is part of a glycan bonded to the protein; "
              f"glycan not fused: {unfused[key]}")
    reasons += glycan
    if reasons:
        failed[key] = "; ".join(reasons)
    available_ligands.append((name, key[1], e["natoms"], e["itp"], e["gro"], e["atomtypes"], inst))

if not_parametrised:
    print("WARNING: ligand parametrisation is off (--no-ligand-param); these ligands are NOT in the topology:")
    for inst in not_parametrised:
        print("  %s %s %s" % inst["key"])
if mode == "off-ff" and failed:
    print(f"Force field {FF_NAME} has no ligand parametrisation; every ligand in the simulated region is "
          f"recorded in {LIGAND_FAILED} (pass --no-ligand-param to run without ligands)")

# The authoritative list: rewritten every time, so stale lines cannot survive.
if failed:
    with open(FAILED_PATH, "w") as f:
        for inst in instances:
            if inst["key"] in failed:
                f.write("%s %s %s %s\n" % (inst["key"] + (" ".join(failed[inst["key"]].split()),)))
    print(f"Wrote {FAILED_PATH}: {len(failed)} ligand instance(s) not simulated as deposited")
elif os.path.isfile(FAILED_PATH):
    os.remove(FAILED_PATH)

if not available_ligands:
    if any(i["entry"] is not None for i in instances):
        print("No ligands within proximity cutoff, skipping merge.")
    else:
        print("No parametrized ligands found, skipping merge.")
    sys.exit(0)

# Sort by resname so all instances of the same molecule type are contiguous
# (GROMACS requires molecules in GRO to match [ molecules ] order in topology)
available_ligands.sort(key=lambda x: x[0])

# Read chain_map.gs to determine protein B residue numbers
residues_b = set()
with open(args.chainmap) as f:
    for line in f:
        if not line.strip().startswith("#"):
            try:
                residues_b.add(int(line.strip()))
            except (ValueError, IndexError):
                pass

# Read protein B chains from chain_map header or sp.gs
# We need to know which chain IDs belong to protein B
# Read from the header comment in chain_map.gs
chains_b = set()
with open(args.chainmap) as f:
    for line in f:
        if "chain(s):" in line:
            chain_str = line.split("chain(s):")[1].strip()
            chains_b = set(c.strip() for c in chain_str.split(","))
            break

# ---- Merge topology ----
with open(args.topol) as f:
    topol_content = f.read()

# Find insertion points
# 1. Insert #include for ligand ITP after the forcefield include
#    (after the first #include line)
lines = topol_content.split("\n")
insert_include_idx = None
for i, line in enumerate(lines):
    if line.strip().startswith("#include") and "forcefield" in line:
        insert_include_idx = i + 1
        break

if insert_include_idx is None:
    # Fallback: insert at the beginning
    insert_include_idx = 0

# 2. Insert ligand molecule counts in [ molecules ] section
molecules_idx = None
for i, line in enumerate(lines):
    if line.strip() == "[ molecules ]":
        molecules_idx = i
        break

# Find where moleculetype sections start (for inserting moleculetype includes)
first_moltype_idx = None
for i, line in enumerate(lines):
    if line.strip().startswith("#include") and "topol_" in line:
        first_moltype_idx = i
        break

if first_moltype_idx is None:
    first_moltype_idx = insert_include_idx + 1

# Build the new topology
# Atomtypes must come BEFORE any moleculetype (GROMACS requirement)
# So: forcefield.itp → atomtypes includes → protein moleculetype includes → ligand moleculetype includes
# A force-field ion (itp "-") needs neither: topol.top already includes its moleculetype.
new_lines = []
includes_added = set()
for i, line in enumerate(lines):
    # Before the first protein moleculetype include, insert ligand moleculetype includes
    if i == first_moltype_idx:
        for resname, chain, natoms, itp, gro, atomtypes, inst in available_ligands:
            if itp != "-" and itp not in includes_added:
                new_lines.append(f'#include "{itp}"')
                includes_added.add(itp)
    new_lines.append(line)
    # After forcefield include, add ligand atomtype includes
    if i == insert_include_idx:
        atomtypes_added = set()
        for resname, chain, natoms, itp, gro, atomtypes, inst in available_ligands:
            if atomtypes != "-" and atomtypes not in atomtypes_added and os.path.isfile(atomtypes):
                new_lines.append(f'#include "{atomtypes}"')
                atomtypes_added.add(atomtypes)

# Find actual end of molecules entries
for i in range(len(new_lines) - 1, -1, -1):
    line = new_lines[i].strip()
    if line and not line.startswith(";") and not line.startswith("[") and not line.startswith("#"):
        # This is the last molecule entry
        mol_insert_idx = i + 1
        break

# Insert ligand molecule entries (each instance is its own molecule type)
ligand_mol_lines = []
for resname, chain, natoms, itp, gro, atomtypes, inst in available_ligands:
    ligand_mol_lines.append(f"{resname:20s} 1")

# Rebuild with ligand molecules inserted
output_lines = new_lines[:mol_insert_idx] + ligand_mol_lines + new_lines[mol_insert_idx:]

with open(args.topol, "w") as f:
    f.write("\n".join(output_lines))

print(f"Updated {args.topol}: added {len(includes_added)} ligand ITP include(s) and {len(ligand_mol_lines)} molecule entry/entries")

# ---- Merge coordinates ----
with open(args.conf) as f:
    gro_lines = f.readlines()

# GRO format: line 1 = title, line 2 = natoms, lines 3..n+2 = atoms, last line = box
title = gro_lines[0]
n_protein_atoms = int(gro_lines[1].strip())
protein_atoms = gro_lines[2:2 + n_protein_atoms]
box_line = gro_lines[2 + n_protein_atoms]

# Read ligand coordinates and append
ligand_atom_lines = []
# Find the highest residue number in the protein GRO
import re
max_resnum = 0
for line in protein_atoms:
    m = re.match(r"\s*(\d+)", line)
    if m:
        resnum = int(m.group(1))
        if resnum > max_resnum:
            max_resnum = resnum

next_resnum = max_resnum + 1
next_atomnum = n_protein_atoms + 1
merged = []   # (name, chain, new resnum, entry) in GRO order

for resname, chain, natoms, itp, gro, atomtypes, inst in available_ligands:
    with open(gro) as f:
        lig_gro_lines = f.readlines()

    n_lig_atoms = int(lig_gro_lines[1].strip())

    for line in lig_gro_lines[2:2 + n_lig_atoms]:
        # Rewrite residue number and atom number
        # GRO format: %5d%-5s%5s%5d%8.3f%8.3f%8.3f
        # First 5 chars: residue number, next 5: residue name, next 5: atom name, next 5: atom number
        old_content = line.rstrip("\n")
        if len(old_content) < 44:
            continue

        # Extract atom name and coordinates (keep as-is)
        atom_name = old_content[10:15]
        coords_and_vel = old_content[20:]  # everything from coordinates onwards

        # The residue name is left-justified in its 5 columns, as GROMACS writes
        # '%5d%-5s%5s%5d'. Right-justified, a three-letter name (SO4, GDP, NAG: every
        # instance 0) left a blank between residue number and name, so split()-based
        # readers took the atom number for x: merge_crystal_waters.py --proximity lost
        # a water next to the 1J2J GTP, and make_disres_en.py run on conf_cutout.gro saw
        # no sulfate restraint at all where 1DFJ has 67 (audit, extra finding).
        gro_resname = resname[:5]
        new_line = f"{next_resnum:5d}{gro_resname:<5s}{atom_name}{next_atomnum:5d}{coords_and_vel}\n"
        ligand_atom_lines.append(new_line)
        next_atomnum += 1

    merged.append((resname, chain, next_resnum, inst["entry"]))
    next_resnum += 1

# Write updated GRO
total_atoms = n_protein_atoms + len(ligand_atom_lines)
with open(args.conf, "w") as f:
    f.write(title)
    f.write(f"{total_atoms:5d}\n")
    for line in protein_atoms:
        f.write(line)
    for line in ligand_atom_lines:
        f.write(line)
    f.write(box_line)

print(f"Updated {args.conf}: {n_protein_atoms} protein + {len(ligand_atom_lines)} ligand = {total_atoms} total atoms")

# ---- Update chain_map.gs if ligand belongs to protein B ----
# The chain is the extracted instance's own, from its PDB record.
new_b_resnums = []
for resname, chain, new_resnum, e in merged:
    if chain in chains_b:
        new_b_resnums.append(new_resnum)
        print(f"Ligand {resname} (chain {chain}) assigned to protein B, resnum {new_resnum}")

if new_b_resnums:
    with open(args.chainmap, "a") as f:
        for resnum in new_b_resnums:
            f.write(f"{resnum}\n")

# ---- Write ligand_residues.gs for make_disres_en.py ----
lig_res_path = os.path.join(os.path.dirname(args.chainmap), "ligand_residues.gs")
with open(lig_res_path, "w") as f:
    f.write("# Residue numbers of parametrized ligands\n")
    for resname, chain, new_resnum, e in merged:
        f.write(f"{new_resnum}\n")

print(f"Wrote {lig_res_path}")

# ---- Record in the manifest where each ligand went ----
# Column 9 of a merged ligand's line is the residue number it got in the merged
# coordinates, the number ligand_residues.gs lists. make_ion_restraints.py looks a
# ligand residue up by that number (and checks the molecule name against the
# coordinates); it used to pair line k of ligand_residues.gs with line k of the
# manifest, which held only while both were in the same order. Merged ligands come
# first, in GRO order, then the rest without a column 9, so nothing is lost.
def manifest_line(e, resnum=None):
    cols = (e["line"].split("\t") if "\t" in e["line"] else e["line"].split())[:8]
    cols += [""] * (8 - len(cols))
    return "\t".join(cols + ([str(resnum)] if resnum is not None else []))


if os.path.isfile(manifest_path) and all(e["line"] for e in entries):
    first = [manifest_line(e, resnum) for _, _, resnum, e in merged]
    done = {id(e) for _, _, _, e in merged}
    rest = [manifest_line(e) for e in entries if id(e) not in done]
    with open(manifest_path, "w") as f:
        f.write("\n".join(first + rest) + "\n")
